import{_ as o,o as e,c as a,a5 as i}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"将字符串转换为16进制字符编码","description":"对于 JavaScript 的 charCodeAt() 方法，它会返回表示给定字符串中的指定字符的 UTF 16 编码的数字。UTF 16 能够涵盖 Unicode 基本多文本平面（Basic Multilingual Plane, BMP）中的所有字符，包括大多数常用的字符和。","frontmatter":{"title":"将字符串转换为16进制字符编码","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语法、变量与数据"],"description":"对于 JavaScript 的 charCodeAt() 方法，它会返回表示给定字符串中的指定字符的 UTF 16 编码的数字。UTF 16 能够涵盖 Unicode 基本多文本平面（Basic Multilingual Plane, BMP）中的所有字符，包括大多数常用的字符和。","sidebarWeight":23,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/基本数据类型-字符串/业务场景/将字符串转换为16进制字符编码.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/02-语法、变量与数据/业务场景/将字符串转换为16进制字符编码.md","filePath":"posts/JavaScript系统教程/02-语法、变量与数据/业务场景/将字符串转换为16进制字符编码.md"}'),r={name:"posts/JavaScript系统教程/02-语法、变量与数据/业务场景/将字符串转换为16进制字符编码.md"};function c(n,t,s,d,l,p){return e(),a("div",null,[...t[0]||(t[0]=[i('<div><h1 id="将字符串转换为16进制字符编码" tabindex="-1">将字符串转换为16进制字符编码 <a class="header-anchor" href="#将字符串转换为16进制字符编码" aria-label="Permalink to &quot;将字符串转换为16进制字符编码&quot;">​</a></h1><blockquote><p>本节目标：理解“将字符串转换为16进制字符编码”的核心思路，并能把它用于实际开发或面试表达。 对于 JavaScript 的 charCodeAt() 方法，它会返回表示给定字符串中的指定字符的 UTF-16 编码的数字。UTF-16 能够涵盖 Unicode 基本多文本平面（Basic Multilingual Plane, BMP）中的所有字符，包括大多数常用的字符和符号。对于 BMP 之外的字符（包括一些非常罕见的汉字），它们被编码为一对“代理对”（surrogate pair）。</p></blockquote><p>因此，如果你处理的字符串只包含 BMP 内的字符（U+0000 到 U+FFFF），charCodeAt() 将工作得很好。</p><p>但是，如果你的字符串可能包含 BMP 之外的字符（即 U+010000 到 U+10FFFF），你需要使用更复杂的逻辑来正确地处理这些字符。</p><p>以下是一个例子，演示如何处理可能包含整个 Unicode 范围内字符的字符串： strToHexCharCode: function(str) { if (str === &quot;&quot;) return &quot;&quot;; let hexCharCode = []; for (let i = 0; i &lt; str.length; i++) { let code = str.codePointAt(i); if (code &gt; 0xFFFF) { i++; // 跳过代理对的第二个部分 } hexCharCode.push(code.toString(16)); } return hexCharCode.join(&quot;&quot;).toUpperCase(); } 在这个版本中，我使用了 codePointAt() 而不是 charCodeAt()。codePointAt() 返回一个 Unicode 代码点，能够正确地处理整个 Unicode 范围（包括代理对）。如果遇到一个代理对，codePointAt() 会返回一个大于 0xFFFF 的代码点，并且我会增加 i 的值以跳过代理对的第二个部分。 这样，这个函数就能正确地处理包括非常罕见的汉字和特殊字符在内的所有 Unicode 字符了。</p><p>对于 UTF-16 编码中的“代理对”（surrogate pairs），第一个代码单元（high surrogate）和第二个代码单元（low surrogate）总是紧密配对出现的。在 JavaScript 字符串中，这样的配对应当是合法和完整的。</p><p>因此，在遇到高代理（high surrogate）并且用 codePointAt() 获取了完整的 Unicode 代码点之后，跳过低代理（low surrogate）通常是安全的，因为低代理本身并不代表一个有效的字符，而仅仅是和高代理一起用来编码一个 BMP 范围之外的字符的。</p><p>下面是一个具体示例： const str = &#39;𠜎&#39;; // 这是一个代理对字符 console.log(str.length); // 输出 2，因为它实际上由两个 UTF-16 编码单元组成 // 使用 codePointAt 获取完整的 Unicode 代码点 const codePoint = str.codePointAt(0); console.log(codePoint.toString(16)); // 输出 &quot;2070e&quot; // 如果跳过第二个代码单元，我们仍然能正确地解析整个字符串 for (let i = 0; i &lt; str.length; i++) { const code = str.codePointAt(i); if (code &gt; 0xFFFF) { i++; // 跳过代理对的第二个部分 } console.log(code.toString(16)); } 当然，在这种做法中有一个隐含的假设，即字符串是“良构”的，也就是说，它不包含孤立的、不完整的代理对。如果你不能保证这一点，那么额外的验证代码可能是必要的。但在大多数正常的操作环境中，代理对应该是完整和良构的。</p></div>',1)])])}const h=o(r,[["render",c]]);export{_ as __pageData,h as default};
